namespace Clog\Entity;

use Clog\Entity\Inventory\InventoryDeleter;
use Clog\Entity\Inventory\InventoryHydrator;
use Clog\Entity\Inventory\InventoryInput;
use Clog\Entity\Inventory\InventoryMutator;
use Clog\Entity\Inventory\InventorySideEffects;
use Clog\Entity\Inventory\InventoryVerifiers;
use Clog\Entity\Item\ItemDeleter;
use Clog\Entity\Item\ItemFinder;
use Clog\Entity\Item\ItemHydrator;
use Clog\Entity\Item\ItemInput;
use Clog\Entity\Item\ItemMutator;
use Clog\Entity\Item\ItemSideEffects;
use Clog\Entity\Item\ItemVerifiers;
use Clog\Entity\Location\LocationDeleter;
use Clog\Entity\Location\LocationHydrator;
use Clog\Entity\Location\LocationInput;
use Clog\Entity\Location\LocationMutator;
use Clog\Entity\Location\LocationSideEffects;
use Clog\Entity\Location\LocationVerifiers;
use Eleph\Runtime\Catalogue\EntityCatalogue;
use Eleph\Runtime\Mutation\EntitySideEffects;
use Eleph\Runtime\Mutation\Managed;
use Eleph\Runtime\Mutation\MutationBuffer;
use Eleph\Runtime\Policy\EntityReadPolicies;
use Eleph\Runtime\Policy\EntityWritePolicies;
use Eleph\Runtime\Policy\NoPolicies;
use Eleph\Runtime\Query\Hydrator;
use Eleph\Runtime\Storage\DeletionRule;
use Eleph\Runtime\Verification\EntityVerifiers;
use Psr\Container\ContainerInterface;
use RuntimeException;

/**
 * What the runtime knows about this project's entities.
 */
final readonly class Catalogue implements EntityCatalogue
{
    public function __construct(
        private ContainerInterface $container,
    ) {

    }

    /**
     * @return list<string>
     */
    public function entities(): array {
        return ['Inventory', 'Item', 'Location'];
    }

    /**
     * @return Hydrator<object>
     */
    public function hydrator(
        string $entity,
    ): Hydrator {
        $service = match ($entity) {
            'Inventory' => $this->container->get(InventoryHydrator::class),
            'Item' => $this->container->get(ItemHydrator::class),
            'Location' => $this->container->get(LocationHydrator::class),
            default => throw new RuntimeException(sprintf('No entity named "%s".', $entity)),
        };

        assert($service instanceof Hydrator);

        return $service;
    }

    public function verifiers(
        string $entity,
    ): EntityVerifiers {
        $service = match ($entity) {
            'Inventory' => $this->container->get(InventoryVerifiers::class),
            'Item' => $this->container->get(ItemVerifiers::class),
            'Location' => $this->container->get(LocationVerifiers::class),
            default => throw new RuntimeException(sprintf('No entity named "%s".', $entity)),
        };

        assert($service instanceof EntityVerifiers);

        return $service;
    }

    public function sideEffects(
        string $entity,
    ): EntitySideEffects {
        $service = match ($entity) {
            'Inventory' => $this->container->get(InventorySideEffects::class),
            'Item' => $this->container->get(ItemSideEffects::class),
            'Location' => $this->container->get(LocationSideEffects::class),
            default => throw new RuntimeException(sprintf('No entity named "%s".', $entity)),
        };

        assert($service instanceof EntitySideEffects);

        return $service;
    }

    public function readPolicies(
        string $entity,
    ): EntityReadPolicies {
        return match ($entity) {
            'Inventory' => new NoPolicies(),
            'Item' => new NoPolicies(),
            'Location' => new NoPolicies(),
            default => throw new RuntimeException(sprintf('No entity named "%s".', $entity)),
        };
    }

    public function writePolicies(
        string $entity,
    ): EntityWritePolicies {
        return match ($entity) {
            'Inventory' => new NoPolicies(),
            'Item' => new NoPolicies(),
            'Location' => new NoPolicies(),
            default => throw new RuntimeException(sprintf('No entity named "%s".', $entity)),
        };
    }

    /**
     * @return array<string, string> "Entity.edge" => target entity
     */
    public function edgeTargets(): array {
        return [
            'Inventory.item' => 'Item',
            'Inventory.location' => 'Location',
        ];
    }

    /**
     * @return array<string, string> "Entity.field" => declared type
     */
    public function fieldTypes(): array {
        return [];
    }

    /**
     * @return list<string>
     */
    public function fieldNames(
        string $entity,
    ): array {
        return match ($entity) {
            'Inventory' => ['createdAt', 'updatedAt', 'postId', 'name', 'dateAdded', 'dateExpiry'],
            'Item' => ['createdAt', 'updatedAt', 'postId', 'name', 'barcode', 'defaultExpiryUnit', 'defaultExpiryValue'],
            'Location' => ['createdAt', 'updatedAt', 'postId', 'name'],
            default => [],
        };
    }

    /**
     * @return list<string>
     */
    public function requiredFields(
        string $entity,
    ): array {
        return match ($entity) {
            'Inventory' => ['name', 'dateAdded'],
            'Item' => ['name'],
            'Location' => ['name'],
            default => [],
        };
    }

    /**
     * @return list<string>
     */
    public function nonNullableFields(
        string $entity,
    ): array {
        return match ($entity) {
            'Inventory' => ['createdAt', 'updatedAt', 'name', 'dateAdded'],
            'Item' => ['createdAt', 'updatedAt', 'name'],
            'Location' => ['createdAt', 'updatedAt', 'name'],
            default => [],
        };
    }

    /**
     * @return list<string>
     */
    public function requiredEdges(
        string $entity,
    ): array {
        return match ($entity) {
            'Inventory' => [],
            'Item' => [],
            'Location' => [],
            default => [],
        };
    }

    /**
     * @return list<string>
     */
    public function uniqueFields(
        string $entity,
    ): array {
        return match ($entity) {
            'Inventory' => ['postId'],
            'Item' => ['postId', 'barcode'],
            'Location' => ['postId', 'name'],
            default => [],
        };
    }

    /**
     * @return array<string, Managed> "Entity.field" => policy
     */
    public function managedFields(): array {
        return [
            'Inventory.createdAt' => Managed::Created,
            'Inventory.updatedAt' => Managed::Modified,
            'Item.createdAt' => Managed::Created,
            'Item.updatedAt' => Managed::Modified,
            'Location.createdAt' => Managed::Created,
            'Location.updatedAt' => Managed::Modified,
        ];
    }

    /**
     * @return list<DeletionRule>
     */
    public function deletionRules(
        string $entity,
    ): array {
        return match ($entity) {
            'Inventory' => InventoryDeleter::rules(),
            'Item' => ItemDeleter::rules(),
            'Location' => LocationDeleter::rules(),
            default => [],
        };
    }

    public function finder(
        string $entity,
    ): object {
        $finder = match ($entity) {
            'Item' => $this->container->get(ItemFinder::class),
            default => throw new RuntimeException(sprintf('%s declares no queries.', $entity)),
        };

        assert(is_object($finder));

        return $finder;
    }

    public function mutatorFor(
        string $entity,
        MutationBuffer $buffer,
    ): object {
        return match ($entity) {
            'Inventory' => new InventoryMutator($buffer),
            'Item' => new ItemMutator($buffer),
            'Location' => new LocationMutator($buffer),
            default => throw new RuntimeException(sprintf('No entity named "%s".', $entity)),
        };
    }

    /**
     * @return list<string>
     */
    public function queryArguments(
        string $entity,
        string $query,
    ): array {
        return match ($entity . '.' . $query) {
            'Item.search' => ['term'],
            default => [],
        };
    }

    /**
     * @return list<string>
     */
    public function actionArguments(
        string $entity,
        string $action,
    ): array {
        return match ($entity . '.' . $action) {

            default => [],
        };
    }

    /**
     * @param array<string, mixed> $args
     * @return array<string, mixed>
     */
    private function decodeInventoryInputActionArguments(
        string $action,
        array $args,
    ): array {
        $input = $this->container->get(InventoryInput::class);

        assert($input instanceof InventoryInput);

        return $input->decodeAction($action, $args);
    }

    /**
     * @param array<string, mixed> $args
     * @return array<string, mixed>
     */
    private function decodeItemInputActionArguments(
        string $action,
        array $args,
    ): array {
        $input = $this->container->get(ItemInput::class);

        assert($input instanceof ItemInput);

        return $input->decodeAction($action, $args);
    }

    /**
     * @param array<string, mixed> $args
     * @return array<string, mixed>
     */
    private function decodeLocationInputActionArguments(
        string $action,
        array $args,
    ): array {
        $input = $this->container->get(LocationInput::class);

        assert($input instanceof LocationInput);

        return $input->decodeAction($action, $args);
    }

    /**
     * @param array<string, mixed> $args
     * @return array<string, mixed>
     */
    public function decodeActionArguments(
        string $entity,
        string $action,
        array $args,
    ): array {
        return match ($entity) {
            'Inventory' => $this->decodeInventoryInputActionArguments($action, $args),
            'Item' => $this->decodeItemInputActionArguments($action, $args),
            'Location' => $this->decodeLocationInputActionArguments($action, $args),
            default => throw new RuntimeException(sprintf('No entity named "%s".', $entity)),
        };
    }

    /**
     * @param array<string, mixed> $input
     */
    public function apply(
        string $entity,
        MutationBuffer $buffer,
        array $input,
    ): void {
        $applier = match ($entity) {
            'Inventory' => $this->container->get(InventoryInput::class),
            'Item' => $this->container->get(ItemInput::class),
            'Location' => $this->container->get(LocationInput::class),
            default => throw new RuntimeException(sprintf('No entity named "%s".', $entity)),
        };

        assert(is_object($applier) && method_exists($applier, 'apply'));

        $applier->apply($buffer, $input);
    }

    /**
     * Everything the application must implement before it can start.
     *
     * @return list<string>
     */
    public function contracts(): array {
        return ['Clog\\Entity\\Item\\Contract\\ItemDefaultExpiryUnitVerifier', 'Clog\\Entity\\Item\\Contract\\ItemDefaultExpiryValueVerifier', 'Clog\\Entity\\Item\\Contract\\ItemSearchQuery'];
    }
}

namespace Clog\Entity\Enum;

/**
 * The unit a default expiry duration is counted in.
 */
enum ExpiryUnit: string
{
    case Days = "days";

    case Months = "months";
}

namespace Clog\Entity\Inventory;

use Clog\Entity\Item\Item;
use Clog\Entity\Location\Location;
use DateTimeImmutable;
use Eleph\Runtime\Identity\EntityId;
use Eleph\Runtime\Query\EdgeLoader;

/**
 * One stocked instance of an item, in a location, with its own expiry.
 */
final class Inventory
{
    private function __construct(
        private readonly EntityId $id,
        private readonly EdgeLoader $edges,
        private readonly DateTimeImmutable $createdAt,
        private readonly DateTimeImmutable $updatedAt,
        private readonly ?int $postId,
        private readonly string $name,
        private readonly DateTimeImmutable $dateAdded,
        private readonly ?DateTimeImmutable $dateExpiry,
    ) {

    }

    public function getId(): EntityId {
        return $this->id;
    }

    /**
     * When the row was first written. Filled by the framework.
     */
    public function getCreatedAt(): DateTimeImmutable {
        return $this->createdAt;
    }

    /**
     * When the row was last written. Filled by the framework.
     */
    public function getUpdatedAt(): DateTimeImmutable {
        return $this->updatedAt;
    }

    /**
     * The wp_posts row this entity projects to, once something creates one. Nullable because nothing in the framework writes it: an entity exists in its own table whether or not a post row was ever made for it.
     */
    public function getPostId(): ?int {
        return $this->postId;
    }

    /**
     * Projected to post_title, so the admin list has something to show.
     */
    public function getName(): string {
        return $this->name;
    }

    /**
     * When this instance entered inventory.
     */
    public function getDateAdded(): DateTimeImmutable {
        return $this->dateAdded;
    }

    /**
     * When it expires. Absent means it does not.
     */
    public function getDateExpiry(): ?DateTimeImmutable {
        return $this->dateExpiry;
    }

    /**
     * @return Item|null
     */
    public function getItem(): ?Item {
        $related = $this->edges->toOne('Inventory', $this->id, 'item');
        assert(null === $related || $related instanceof Item);

        return $related;
    }

    /**
     * @return Location|null
     */
    public function getLocation(): ?Location {
        $related = $this->edges->toOne('Inventory', $this->id, 'location');
        assert(null === $related || $related instanceof Location);

        return $related;
    }

    public static function of(
        EntityId $id,
        EdgeLoader $edges,
        DateTimeImmutable $createdAt,
        DateTimeImmutable $updatedAt,
        ?int $postId,
        string $name,
        DateTimeImmutable $dateAdded,
        ?DateTimeImmutable $dateExpiry,
    ): self {
        return new self($id, $edges, $createdAt, $updatedAt, $postId, $name, $dateAdded, $dateExpiry);
    }
}

namespace Clog\Entity\Inventory;

use Eleph\Runtime\Identity\EntityId;
use Eleph\Runtime\Mutation\Deletion;
use Eleph\Runtime\Storage\DeletionRule;
use Eleph\Runtime\UnitOfWork\UnitOfWork;

/**
 * Removes a Inventory, and whatever its edges say goes with it.
 */
final class InventoryDeleter
{
    public function __construct(
        private readonly UnitOfWork $work,
    ) {

    }

    /**
     * Registers the removal. Nothing happens until the unit of work commits.
     */
    public function delete(
        EntityId $id,
    ): void {
        $this->work->delete(new Deletion('Inventory', $id));
    }

    /**
     * @return list<DeletionRule>
     */
    public static function rules(): array {
        return [];
    }
}

namespace Clog\Entity\Inventory;

use DateTimeImmutable;
use Eleph\Runtime\Query\EdgeLoader;
use Eleph\Runtime\Query\Hydrator;
use Eleph\Runtime\Query\ValueDecoder;
use Eleph\Runtime\Storage\Record;

/**
 * Builds a Inventory from a stored row.
 *
 * @implements Hydrator<Inventory>
 */
final readonly class InventoryHydrator implements Hydrator
{
    public function __construct(
        private ValueDecoder $decode,
    ) {

    }

    public function hydrate(
        Record $record,
        EdgeLoader $edges,
    ): Inventory {
        return Inventory::of(
            $record->id,
            $edges,
            $this->createdAt($record),
            $this->updatedAt($record),
            $this->postId($record),
            $this->name($record),
            $this->dateAdded($record),
            $this->dateExpiry($record),
        );
    }

    private function createdAt(
        Record $record,
    ): DateTimeImmutable {
        $value = $record->value('createdAt');

        return $this->decode->datetime($value, 'Inventory.createdAt');
    }

    private function updatedAt(
        Record $record,
    ): DateTimeImmutable {
        $value = $record->value('updatedAt');

        return $this->decode->datetime($value, 'Inventory.updatedAt');
    }

    private function postId(
        Record $record,
    ): ?int {
        $value = $record->value('postId');

        return null === $value ? null : $this->decode->int($value, 'Inventory.postId');
    }

    private function name(
        Record $record,
    ): string {
        $value = $record->value('name');

        return $this->decode->string($value, 'Inventory.name');
    }

    private function dateAdded(
        Record $record,
    ): DateTimeImmutable {
        $value = $record->value('dateAdded');

        return $this->decode->datetime($value, 'Inventory.dateAdded');
    }

    private function dateExpiry(
        Record $record,
    ): ?DateTimeImmutable {
        $value = $record->value('dateExpiry');

        return null === $value ? null : $this->decode->datetime($value, 'Inventory.dateExpiry');
    }
}

namespace Clog\Entity\Inventory;

use DateTimeImmutable;
use Eleph\Runtime\Identity\Identifier;
use Eleph\Runtime\Mutation\MutationBuffer;
use Eleph\Runtime\Query\ValueDecoder;
use InvalidArgumentException;

/**
 * Turns raw input into pending Inventory changes.
 */
final readonly class InventoryInput
{
    public function __construct(
        private ValueDecoder $decode,
    ) {

    }

    private function postId(
        mixed $value,
    ): ?int {
        if (null === $value) {
            return null;
        }

        return $this->decode->int($value, 'Inventory.postId');
    }

    private function name(
        mixed $value,
    ): ?string {
        if (null === $value) {
            return null;
        }

        return $this->decode->string($value, 'Inventory.name');
    }

    private function dateAdded(
        mixed $value,
    ): ?DateTimeImmutable {
        if (null === $value) {
            return null;
        }

        return $this->decode->datetime($value, 'Inventory.dateAdded');
    }

    private function dateExpiry(
        mixed $value,
    ): ?DateTimeImmutable {
        if (null === $value) {
            return null;
        }

        return $this->decode->datetime($value, 'Inventory.dateExpiry');
    }

    /**
     * @return list<Identifier>
     */
    private function item(
        mixed $value,
    ): array {
        if (null === $value) {
            return [];
        }

        return [$this->decode->id($value, 'Inventory.item')];
    }

    /**
     * @return list<Identifier>
     */
    private function location(
        mixed $value,
    ): array {
        if (null === $value) {
            return [];
        }

        return [$this->decode->id($value, 'Inventory.location')];
    }

    /**
     * Seeds declared defaults on create and applies explicit input.
     * Absent update keys and existing pending values are not reset by defaults.
     *
     * @param array<string, mixed> $input
     */
    public function apply(
        MutationBuffer $buffer,
        array $input,
    ): void {
        if (array_key_exists('postId', $input)) {
            $buffer->set('postId', $this->postId($input['postId']));
        }

        if (array_key_exists('name', $input)) {
            $buffer->set('name', $this->name($input['name']));
        }

        if (array_key_exists('dateAdded', $input)) {
            $buffer->set('dateAdded', $this->dateAdded($input['dateAdded']));
        }

        if (array_key_exists('dateExpiry', $input)) {
            $buffer->set('dateExpiry', $this->dateExpiry($input['dateExpiry']));
        }

        if (array_key_exists('item', $input)) {
            $buffer->edge('item')->set($this->item($input['item']));
        }

        if (array_key_exists('location', $input)) {
            $buffer->edge('location')->set($this->location($input['location']));
        }
    }

    /**
     * @param array<string, mixed> $args
     * @return array<string, mixed>
     */
    public function decodeAction(
        string $action,
        array $args,
    ): array {
        return match ($action) {

            default => throw new InvalidArgumentException(sprintf('Unknown action %s.', $action)),
        };
    }
}

namespace Clog\Entity\Inventory;

use DateTimeImmutable;
use Eleph\Runtime\Identity\Identifier;
use Eleph\Runtime\Mutation\ActionCall;
use Eleph\Runtime\Mutation\MutationContext;

/**
 * A pending Inventory mutation, with exact types.
 */
final readonly class InventoryMutationContext implements MutationContext
{
    private function __construct(
        private MutationContext $context,
    ) {

    }

    /**
     * @return list<ActionCall>
     */
    public function actions(): array {
        return $this->context->actions();
    }

    public function originalEntity(): ?object {
        return $this->context->originalEntity();
    }

    public function id(): Identifier {
        return $this->context->id();
    }

    public function entity(): string {
        return $this->context->entity();
    }

    public function isCreate(): bool {
        return $this->context->isCreate();
    }

    public function original(
        string $field,
    ): mixed {
        return $this->context->original($field);
    }

    public function pending(
        string $field,
    ): mixed {
        return $this->context->pending($field);
    }

    public function isChanged(
        string $field,
    ): bool {
        return $this->context->isChanged($field);
    }

    /**
     * @return array<string, mixed>
     */
    public function changes(): array {
        return $this->context->changes();
    }

    /**
     * @return list<Identifier>
     */
    public function pendingEdge(
        string $edge,
    ): array {
        return $this->context->pendingEdge($edge);
    }

    public function isEdgeChanged(
        string $edge,
    ): bool {
        return $this->context->isEdgeChanged($edge);
    }

    public function originalCreatedAt(): ?DateTimeImmutable {
        $value = $this->context->original('createdAt');
        assert(null === $value || $value instanceof DateTimeImmutable);

        return $value;
    }

    public function pendingCreatedAt(): ?DateTimeImmutable {
        $value = $this->context->pending('createdAt');
        assert(null === $value || $value instanceof DateTimeImmutable);

        return $value;
    }

    public function originalUpdatedAt(): ?DateTimeImmutable {
        $value = $this->context->original('updatedAt');
        assert(null === $value || $value instanceof DateTimeImmutable);

        return $value;
    }

    public function pendingUpdatedAt(): ?DateTimeImmutable {
        $value = $this->context->pending('updatedAt');
        assert(null === $value || $value instanceof DateTimeImmutable);

        return $value;
    }

    public function originalPostId(): ?int {
        $value = $this->context->original('postId');
        assert(null === $value || is_int($value));

        return $value;
    }

    public function pendingPostId(): ?int {
        $value = $this->context->pending('postId');
        assert(null === $value || is_int($value));

        return $value;
    }

    public function originalName(): ?string {
        $value = $this->context->original('name');
        assert(null === $value || is_string($value));

        return $value;
    }

    public function pendingName(): ?string {
        $value = $this->context->pending('name');
        assert(null === $value || is_string($value));

        return $value;
    }

    public function originalDateAdded(): ?DateTimeImmutable {
        $value = $this->context->original('dateAdded');
        assert(null === $value || $value instanceof DateTimeImmutable);

        return $value;
    }

    public function pendingDateAdded(): ?DateTimeImmutable {
        $value = $this->context->pending('dateAdded');
        assert(null === $value || $value instanceof DateTimeImmutable);

        return $value;
    }

    public function originalDateExpiry(): ?DateTimeImmutable {
        $value = $this->context->original('dateExpiry');
        assert(null === $value || $value instanceof DateTimeImmutable);

        return $value;
    }

    public function pendingDateExpiry(): ?DateTimeImmutable {
        $value = $this->context->pending('dateExpiry');
        assert(null === $value || $value instanceof DateTimeImmutable);

        return $value;
    }

    public function pendingItem(): ?Identifier {
        return $this->context->pendingEdge('item')[0] ?? null;
    }

    public function isItemChanged(): bool {
        return $this->context->isEdgeChanged('item');
    }

    public function pendingLocation(): ?Identifier {
        return $this->context->pendingEdge('location')[0] ?? null;
    }

    public function isLocationChanged(): bool {
        return $this->context->isEdgeChanged('location');
    }

    public static function of(
        MutationContext $context,
    ): self {
        return new self($context);
    }
}

namespace Clog\Entity\Inventory;

use DateTimeImmutable;
use Eleph\Runtime\Identity\Identifier;
use Eleph\Runtime\Mutation\MutationBuffer;

/**
 * Pending changes to a Inventory.
 */
final class InventoryMutator
{
    public function __construct(
        private readonly MutationBuffer $buffer,
    ) {

    }

    public function setPostId(
        ?int $postId,
    ): self {
        $this->buffer->set('postId', $postId);

        return $this;
    }

    public function setName(
        string $name,
    ): self {
        $this->buffer->set('name', $name);

        return $this;
    }

    public function setDateAdded(
        DateTimeImmutable $dateAdded,
    ): self {
        $this->buffer->set('dateAdded', $dateAdded);

        return $this;
    }

    public function setDateExpiry(
        ?DateTimeImmutable $dateExpiry,
    ): self {
        $this->buffer->set('dateExpiry', $dateExpiry);

        return $this;
    }

    /**
     * Point this at one Item, or at nothing.
     */
    public function setItem(
        ?Identifier $item,
    ): self {
        $this->buffer->edge('item')->set(null === $item ? [] : [$item]);

        return $this;
    }

    /**
     * Point this at one Location, or at nothing.
     */
    public function setLocation(
        ?Identifier $location,
    ): self {
        $this->buffer->edge('location')->set(null === $location ? [] : [$location]);

        return $this;
    }
}

namespace Clog\Entity\Inventory;

use DateTimeImmutable;
use Eleph\Runtime\Identity\Identifier;
use Eleph\Runtime\Mutation\ActionCall;
use Eleph\Runtime\Mutation\EdgeMutation;
use Eleph\Runtime\Mutation\MutableMutationContext;

/**
 * A pending Inventory mutation, with exact types.
 */
final readonly class InventoryPreCommitContext implements MutableMutationContext
